    pairs[0] = ETH_USDC_POOL;
    IAccessHub(ACCESS_HUB).killGauge(pairs);
    // move time forward to next period
    vm.warp(block.timestamp + 1 weeks);
    IVoter(VOTER).distribute(gauge);
}
```
